    const human=silhouette(270,192,e.scene==='cage'?'高浚 / 高涣':e.scene==='saw'?'穆嵩（待核）':e.scene==='wrestle'?'高绰':e.scene==='assassin'?'高澄':e.scene==='scorpion'?'受刑者未详':e.scene==='dog'?(e.id==='D24'?'母子 / 名牌示意':'受害者未详'):e.scene==='arrow'?'攻城扮演者':'关系对象');
